// ============================================
// VALIDATION INPUT - Claude Call With Skills (Batch Mode)
// ============================================

const input = $input.first().json;
const body = input.body || input;
const ctx = body.context || {};

const errors = [];

// --- REQUIRED: api_key ---
const apiKey = body.api_key || ctx.api_key;
if (!apiKey || typeof apiKey !== 'string') {
  errors.push('api_key requis (Anthropic key)');
}

// --- REQUIRED: callback_url (for async results) ---
const callbackUrl = body.callback_url || ctx.callback_url;
if (!callbackUrl || typeof callbackUrl !== 'string') {
  errors.push('callback_url requis pour recevoir les résultats');
}

// --- correlation_id (auto-generate if not provided) ---
const correlationId = body.correlation_id || ctx.correlation_id || `batch-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;

// --- REQUIRED: model ---
const model = body.model || ctx.model || 'claude-sonnet-4-20250514';

// --- REQUIRED: messages ---
const messages = body.messages || ctx.messages;
if (!messages || !Array.isArray(messages) || messages.length === 0) {
  errors.push('messages requis');
}

// --- REQUIRED: container with skills ---
const container = body.container || ctx.container;
if (!container || !container.skills || container.skills.length === 0) {
  errors.push('container.skills requis (ex: [{ type: "anthropic", skill_id: "docx" }])');
}

// --- Skills API requires specific betas ---
const SKILLS_BETAS = ['code-execution-2025-08-25', 'skills-2025-10-02'];
const betas = body.betas || ctx.betas || SKILLS_BETAS;

const system = body.system || ctx.system || null;
const maxTokens = parseInt(body.max_tokens || ctx.max_tokens || 16000);

// --- Skills API requires code_execution tool ---
let tools = body.tools || ctx.tools || [];
const hasCodeExecution = tools.some(t => t.type === 'code_execution_20250825' || t.name === 'code_execution');
if (!hasCodeExecution) {
  tools = [{ type: 'code_execution_20250825', name: 'code_execution' }, ...tools];
}

const metadata = body.metadata || ctx.metadata || {};

if (errors.length > 0) {
  return {
    valid: false,
    errors: errors,
    correlation_id: correlationId,
    metadata: metadata
  };
}

return {
  valid: true,
  api_key: apiKey.trim(),
  model: model,
  betas: betas,
  system: system,
  messages: messages,
  max_tokens: maxTokens,
  container: container,
  tools: tools,
  callback_url: callbackUrl,
  correlation_id: correlationId,
  metadata: metadata,
  submitted_at: new Date().toISOString()
};

const input = $input.first().json;

return {
  success: false,
  status: 'error',
  correlation_id: input.correlation_id,
  error: {
    code: 'VALIDATION_ERROR',
    message: input.errors.join(', '),
    http_status: 400
  },
  metadata: input.metadata
};

