={{ (() => {
  const data = $json;

  // Build the batch request with a single message request
  const messageParams = {
    model: data.model,
    max_tokens: data.max_tokens,
    messages: data.messages,
    container: data.container,
    tools: data.tools
  };
  if (data.system) messageParams.system = data.system;

  const batchRequest = {
    requests: [
      {
        custom_id: data.correlation_id,
        params: messageParams
      }
    ]
  };

  return JSON.stringify(batchRequest);
})() }}

