// ============================================
// PREPARE BATCH DATA FOR REDIS STORAGE
// ============================================

const batchResponse = $input.first().json;
const prevData = $('Validate Input').first().json;

// Check for batch creation error
if (batchResponse.error || !batchResponse.id) {
  return {
    success: false,
    status: 'error',
    correlation_id: prevData.correlation_id,
    error: {
      code: batchResponse.error?.type || 'BATCH_CREATE_ERROR',
      message: batchResponse.error?.message || 'Failed to create batch',
      http_status: 500
    },
    metadata: prevData.metadata
  };
}

// Prepare data for Redis storage
return {
  success: true,
  batch_id: batchResponse.id,
  processing_status: batchResponse.processing_status,
  correlation_id: prevData.correlation_id,
  callback_url: prevData.callback_url,
  api_key: prevData.api_key,
  model: prevData.model,
  metadata: prevData.metadata,
  submitted_at: prevData.submitted_at,
  expires_at: batchResponse.expires_at,
  // For Redis XADD
  redis_data: {
    batch_id: batchResponse.id,
    correlation_id: prevData.correlation_id,
    callback_url: prevData.callback_url,
    api_key: prevData.api_key,
    model: prevData.model,
    status: 'pending',
    submitted_at: prevData.submitted_at,
    metadata: JSON.stringify(prevData.metadata)
  }
};

// ============================================
// BUILD SUCCESS RESPONSE (202 Accepted)
// ============================================

const batchData = $('Prepare Batch Data').first().json;
const redisResponse = $input.first().json;

return {
  success: true,
  status: 'processing',
  batch_id: batchData.batch_id,
  correlation_id: batchData.correlation_id,
  message: 'Batch submitted successfully. Results will be sent to callback_url when ready.',
  expires_at: batchData.expires_at,
  redis_stream_id: redisResponse.stream_id || null,
  metadata: batchData.metadata
};

// Batch creation failed - return error
const data = $json;
return {
  success: false,
  status: 'error',
  correlation_id: data.correlation_id,
  error: data.error,
  metadata: data.metadata
};
